const item = $input.first();
const body = item.json.body ?? {};
const binary = item.binary ?? {};

const readString = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) {
      return value.trim();
    }
  }
  return '';
};

const action = readString(body.action);
const sessionId = readString(body.sessionId);

// Canonical patient context used by every downstream node.
// The first aliases reflect the current webhook contract; the patient* aliases
// preserve compatibility with the previous web payload during the transition.
const patientId = readString(body.pacientId, body.patientId);

const patientFullName = readString(
  body.pacienteFullName,
  body.patientFullName,
  body.patientName
);

const patientPhoneNumber = readString(
  body.pacientPhoneNumber,
  body.patientPhoneNumber
);

const patientEmail = readString(
  body.pacientEmail,
  body.patientEmail
);

const chatInput = readString(body.chatInput);
const declaredMessageType = readString(body.messageType).toLowerCase();

const binaryFields = Object.keys(binary);
const audioBinaryField = binaryFields[0] ?? null;

const validationErrors = [];

if (action !== 'sendMessage') {
  validationErrors.push('body.action must be "sendMessage"');
}

if (!sessionId) {
  validationErrors.push('body.sessionId is required');
}

if (!patientId) {
  validationErrors.push('body.pacientId is required');
}

if (!patientFullName) {
  validationErrors.push('body.pacienteFullName is required');
}

// patientPhoneNumber is optional.

if (!patientEmail) {
  validationErrors.push('body.pacientEmail is required');
}

let messageType = 'text';

if (declaredMessageType === 'audio') {
  messageType = 'audio';

  if (!audioBinaryField) {
    validationErrors.push('audio message requires one n8n binary file');
  }
} else if (!chatInput) {
  validationErrors.push(
    'text message requires a non-empty body.chatInput'
  );
}

const routeIndex =
  validationErrors.length > 0
    ? 2
    : messageType === 'audio'
      ? 0
      : 1;

return [
  {
    json: {
      headers: item.json.headers ?? {},
      params: item.json.params ?? {},
      query: item.json.query ?? {},
      body,
      action,
      sessionId,
      patientId,
      patientFullName,
      patientPhoneNumber,
      patientEmail,
      messageType,
      chatInput,
      audioBinaryField,
      routeIndex,
      validationErrors,
    },
    binary,
  },
];

