const success = payloadValid;
const looksRateLimited = /rate.?limit|quota|too many requests|ratelimitexceeded|userratelimitexceeded/.test(lower);
const networkTransient = /timeout|timed out|econnreset|econnrefused|enotfound|eai_again|socket hang up|connection reset|connection closed|connection aborted|temporar|network/.test(lower);
let retryable = false;
if (!success) {
  if ([408,425,429].includes(statusCode)) retryable = true;
  else if (statusCode >= 500 && statusCode <= 599) retryable = true;
  else if (statusCode === 403 && looksRateLimited) retryable = true;
  else if (networkTransient) retryable = true;
  else if (!statusCode && !/400|401|403|404|422/.test(lower)) retryable = true;
}
return [{json: {...response, _retry: {attempt:1, success, retryable, exhausted: !success && retryable && 1 >= 3, statusCode: statusCode || null, message: success ? null : message.slice(0,1500)}}}];

