const agent = $('Essentia Scheduling Agent').first().json ?? {};
const intake = $('Normalize & Validate Input').first().json ?? {};
const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];

function parseMaybeJson(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'object') return value;
  if (typeof value !== 'string') return null;
  const text = value.trim();
  if (!text) return null;
  try { return JSON.parse(text); } catch {}
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(text.slice(first, last + 1)); } catch {}
  }
  return null;
}

function unwrap(value, depth = 0) {
  if (depth > 5) return value;
  let v = parseMaybeJson(value) ?? value;
  if (Array.isArray(v)) return v.length ? unwrap(v[0], depth + 1) : null;
  if (!v || typeof v !== 'object') return v;
  for (const k of ['body','data','response','result','appointment']) {
    if (v[k] !== undefined && v[k] !== null) {
      const nested = unwrap(v[k], depth + 1);
      if (nested && typeof nested === 'object') return nested;
    }
  }
  return v;
}

let event = null;
for (let i = steps.length - 1; i >= 0; i--) {
  const step = steps[i] ?? {};
  const tool = step.action?.tool;
  if (tool !== 'book_appointment' && tool !== 'cancel_appointment') continue;
  const payload = unwrap(step.observation);
  if (!payload || typeof payload !== 'object') continue;
  const status = String(payload.status ?? '').toLowerCase();
  if (tool === 'book_appointment' && status === 'scheduled') {
    event = { eventType:'appointment_booked', payload, toolInput:step.action?.toolInput ?? {} };
    break;
  }
  if (tool === 'cancel_appointment' && status === 'cancelled') {
    event = { eventType:'appointment_cancelled', payload, toolInput:step.action?.toolInput ?? {} };
    break;
  }
}

if (!event) return [{json:{shouldNotify:false, reason:'no_successful_mutation'}}];

const a = event.payload;
const appointmentId = String(a.id ?? a.appointment_id ?? '').trim();
const recipient = String(intake.patientEmail ?? intake.body?.patientEmail ?? '').trim();
if (!appointmentId || !recipient) {
  return [{json:{shouldNotify:false, reason:'missing_appointment_id_or_email'}}];
}

