const serviceName = String(a.service_name ?? 'Consulta médica');
const doctorName = String(a.doctor_name ?? '').trim();
const startsAtRaw = a.starts_at;
const startsAt = startsAtRaw ? new Date(startsAtRaw) : null;
const validDate = startsAt && !Number.isNaN(startsAt.getTime());
const fmtDate = validDate ? new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric'}).format(startsAt) : null;
const fmtTime = validDate ? new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hour12:false}).format(startsAt) : null;
let formattedPrice = null;
if (a.price_amount !== null && a.price_amount !== undefined && a.price_amount !== '') {
  const p = Number(a.price_amount);
  if (!Number.isNaN(p)) formattedPrice = new Intl.NumberFormat('pt-BR',{style:'currency',currency:String(a.currency ?? 'BRL')}).format(p);
}
const cancellationReason = a.cancellation_reason ? String(a.cancellation_reason) : null;

const lines = event.eventType === 'appointment_booked'
  ? [
      `Olá, ${patientName}.`, '', 'Sua consulta foi agendada com sucesso.', '',
      `Serviço: ${serviceName}`,
      doctorName ? `Profissional: ${doctorName}` : null,
      fmtDate ? `Data: ${fmtDate}` : null,
      fmtTime ? `Horário: ${fmtTime}` : null,
      formattedPrice ? `Valor: ${formattedPrice}` : null,
      '', 'Atenciosamente,', 'Essentia'
    ]
  : [
      `Olá, ${patientName}.`, '', 'O cancelamento da sua consulta foi confirmado.', '',
      `Serviço: ${serviceName}`,
      doctorName ? `Profissional: ${doctorName}` : null,
      fmtDate ? `Data: ${fmtDate}` : null,
      fmtTime ? `Horário: ${fmtTime}` : null,
      cancellationReason ? `Motivo: ${cancellationReason}` : null,
      '', 'Atenciosamente,', 'Essentia'
    ];
const message = lines.filter(v => v !== null).join('\n');
const subject = event.eventType === 'appointment_booked'
  ? 'Confirmação de consulta — Essentia'
  : 'Cancelamento de consulta — Essentia';
const logicalId = `${event.eventType}:${appointmentId}`;

return [{json:{
  shouldNotify:true,
