return [{json:{...n,retryable,terminal:!retryable,terminalReason:retryable?null:'permanent_error',errorMeta:err,retryJob:job}}];

const n=$('Detect Successful Mutation').first().json;
const s=$('Normalize Retry Schedule').item.json;
const j=s.retryJob, e=$json.error??$json;
let ser; try{ser=JSON.stringify(e)}catch{ser=String(e)}
const msg=String(e?.message??e?.description??ser);
const cs=[e?.httpCode,e?.statusCode,e?.status,e?.response?.statusCode,e?.response?.status].map(Number);
let code=cs.find(v=>Number.isInteger(v)&&v>=100&&v<=599);
if(!code){const m=ser.match(/\b([45]\d{2})\b/); if(m) code=Number(m[1]);}
const low=`${msg} ${ser}`.toLowerCase();
const rate=/rate.?limit|quota|userratelimitexceeded|ratelimitexceeded/.test(low);
const net=/timeout|timed out|econnreset|econnrefused|enotfound|eai_again|socket hang up|connection reset|connection closed|connection aborted|temporar|network/.test(low);
let retryable=false;
if([408,425,429].includes(code)) retryable=true;
else if(code>=500&&code<=599) retryable=true;
else if(code===403&&rate) retryable=true;
else if(net) retryable=true;
else if(!code) retryable=true;
const failed=Number(j.attempt), max=Number(j.maxAttempts), exhausted=failed>=max, terminal=!retryable||exhausted;
const err={statusCode:code??null,message:msg.slice(0,1500),retryable,occurredAt:new Date().toISOString()};
