  next={...next,attempt:a,delaySeconds:delay,nextAttemptAt:new Date(Date.now()+delay*1000).toISOString(),status:'scheduled'};
}
return [{json:{...n,retryable,exhausted,terminal,terminalReason:reason,errorMeta:err,retryJob:next}}];

const n=$('Detect Successful Mutation').first().json, i=$input.first().json;
const reason=i.terminalReason??(i.retryable===false?'permanent_error':'max_attempts_exhausted');
const terminalStatus=reason==='permanent_error'?'failed_permanent':'dead_letter';
const job=i.retryJob??{jobId:n.logicalId,eventType:n.eventType,appointmentId:n.appointmentId,recipient:n.recipient,subject:n.subject,message:n.message,attempt:0,maxAttempts:n.maxAsyncAttempts,lastError:i.errorMeta??null};
