const prepared = $('Prepare Response Review Input').first().json;
const raw = $input.first().json;

let review =
  raw.output ??
  raw.result ??
  raw;

if (typeof review === 'string') {
  try {
    review = JSON.parse(review);
  } catch {
    throw new Error('Corrector returned an invalid structured response.');
  }
}

if (
  review &&
  typeof review.output === 'object' &&
  review.output !== null
) {
  review = review.output;
}

const allowedDecisions = new Set(['pass', 'correct', 'block']);
const decision = String(review?.decision ?? '').toLowerCase();

if (!allowedDecisions.has(decision)) {
  throw new Error(`Invalid corrector decision: ${decision || '<empty>'}`);
}

const originalText = prepared.assistantDraft;
const candidateText =
  typeof review?.finalText === 'string'
    ? review.finalText.trim()
    : '';

let output;

if (decision === 'pass') {
  output = originalText;
} else {
  if (!candidateText) {
    throw new Error(
      `Corrector decision "${decision}" requires a non-empty finalText.`
    );
  }
  output = candidateText;
}

return [{
  json: {
    ...prepared.originalAgentResult,
    output,
    qualityReview: {
      decision,
      severity: review?.severity ?? 'none',
      issues: Array.isArray(review?.issues) ? review.issues : [],
      flags: review?.flags ?? {},
    },
  }
}];

const prepared = $('Prepare Response Review Input').first().json;

return [{
  json: {
    ...prepared.originalAgentResult,
    output:
      'Não consegui validar minha resposta com segurança neste momento. Por favor, tente novamente.',
    qualityReview: {
      decision: 'block',
      severity: 'high',
      issues: ['response_corrector_unavailable'],
      flags: {
        reviewerUnavailable: true,
      },
    },
  }
}];

const input = $input.first().json ?? {};

const sourceText =
  input.message ??
  input.output ??
  input.text;

if (typeof sourceText !== 'string' || !sourceText.trim()) {
  throw new Error('TTS Speech Normalizer requires a non-empty textual message.');
}

return [{
  json: {
    ...input,
    message: sourceText.trim(),
    speechNormalizationInput: {
      locale: 'pt-BR',
      sourceText: sourceText.trim(),
    },
  },
}];

