const prepared = $('Prepare Speech Normalization Input').first().json;
const raw = $input.first().json;

let normalized =
  raw.output ??
  raw.result ??
  raw;

if (typeof normalized === 'string') {
  try {
    normalized = JSON.parse(normalized);
  } catch {
    throw new Error('Speech normalizer returned invalid structured output.');
  }
}

if (
  normalized &&
  typeof normalized.output === 'object' &&
  normalized.output !== null
) {
  normalized = normalized.output;
}

const ttsText =
  typeof normalized?.ttsText === 'string'
    ? normalized.ttsText.trim()
    : '';

if (!ttsText) {
  throw new Error('Speech normalizer returned an empty ttsText.');
}

const remainingDigits = /\d/.test(ttsText);
const markdownPatterns = [
  /```/,
  /(^|\n)\s{0,3}#{1,6}\s+/m,
  /\*\*[^*]+\*\*/,
  /__[^_]+__/,
  /~~[^~]+~~/,
  /\[[^\]]+\]\([^)]+\)/,
];

const remainingMarkdown = markdownPatterns.some((pattern) =>
  pattern.test(ttsText)
);

if (remainingDigits || remainingMarkdown) {
  throw new Error(
    `Speech normalization validation failed. remainingDigits=${remainingDigits}, remainingMarkdown=${remainingMarkdown}`
  );
}

return [{
  json: {
    ...prepared,
    message: prepared.message,
    ttsText,
    speechNormalization: {
      changed: Boolean(normalized?.changed),
      transformations: Array.isArray(normalized?.transformations)
        ? normalized.transformations
        : [],
      degraded: false,
    },
  },
}];

const prepared = $('Prepare Speech Normalization Input').first().json;

return [{
  json: {
    ...prepared,
    message: prepared.message,
    ttsText: prepared.message,
    speechNormalization: {
      changed: false,
      transformations: [],
      degraded: true,
      reason: 'speech_normalizer_unavailable_or_invalid',
    },
  },
}];

const input = $input.first().json ?? {};

const ttsText =
  typeof input.ttsText === 'string' && input.ttsText.trim()
    ? input.ttsText.trim()
    : input.message;

if (typeof ttsText !== 'string' || !ttsText.trim()) {
  throw new Error('No valid TTS text available.');
}

return [{
  json: {
    ...input,
    ttsText: ttsText.trim(),
  },
}];
